H=C.HOUR_MS
DEV_START=S.CORE.milliseconds('2024-10-14T00:00:00Z')
ELIGIBLE=S.CORE.milliseconds('2024-12-14T00:00:00Z')


@pytest.fixture(scope='module')
def native_fixture(tmp_path_factory):
    root=make_fixture(tmp_path_factory.mktemp('c267-SYNTHETIC-source'),hours=3,trade_interval='1m')
    snapshot=json.loads((root/'snapshot.json').read_bytes());snapshot['serverTime']=S.CORE.milliseconds('2024-12-13T00:00:00Z')
    snapshot_sha=write_json(root/'snapshot.json',snapshot)
    base=json.loads((root/'filters.v2.json').read_bytes())
    base['snapshots'][0].update(captured_at='2024-12-13T01:00:00Z',server_time='2024-12-13T00:00:00Z',sha256=snapshot_sha)
    base['fold_bindings']={k:'2024-12-13T01:00:00Z' for k in base['fold_bindings']}
    prior_sha=write_json(root/'filters.v2.json',base)
    filters=json.loads((root/'filters.json').read_bytes());filters.update(snapshots=base['snapshots'],fold_bindings=base['fold_bindings'])
    filters['supersedes']['byte_sha256']=prior_sha;write_json(root/'filters.json',filters)
    pit=json.loads((root/'pit.json').read_bytes())
    pit['weeks'].insert(0,dict(pit['weeks'][0],monday_ms=ELIGIBLE-5*24*H,monday_utc='2024-12-09T00:00:00Z'))
    write_json(root/'pit.json',pit);repin_synthetic_manifest(root,json.loads((root/'manifest.json').read_bytes()))
    return root


def issue(monkeypatch,root,common):
    monkeypatch.setattr(A,'ROOT',root)
    monkeypatch.setattr(A,'_git',lambda *args:str(common) if args==('rev-parse','--git-common-dir') else pytest.fail(args))
    monkeypatch.setattr(A,'_authenticate_metadata',lambda side:('a'*40,'b'*64,root/'store',fixture_artifacts(root),DEV_START,END))


def edit_trade(root,edit,symbol='BTCUSDT'):
    manifest=json.loads((root/'manifest.json').read_bytes())
    record=next(r for r in manifest['files'] if (r['series'],r['symbol'])==('klines',symbol))
    path=root/'store'/record['path']
    with zipfile.ZipFile(path) as z:name=z.namelist()[0];lines=z.read(name).splitlines()
    with zipfile.ZipFile(path,'w',compression=zipfile.ZIP_DEFLATED) as z:z.writestr(name,b'\n'.join(edit(lines))+b'\n')
    Path(str(path)+'.ok').write_text(hashlib.sha256(path.read_bytes()).hexdigest())
    record.update(M.scan_archive(str(path),record['path']));repin_synthetic_manifest(root,manifest)


def test_two_own_side_scopes_do_not_borrow_claim_or_source_identity(native_fixture,tmp_path,monkeypatch):
    issue(monkeypatch,native_fixture,tmp_path/'SYNTHETIC-common')
    with A.development_authority(1) as long_cap,A.development_authority(-1) as short_cap:
        assert long_cap.claim_path!=short_cap.claim_path
        long,short=S.DevelopmentSource(long_cap),S.DevelopmentSource(short_cap)
        assert long.side==1 and short.side==-1 and long.start_ms==DEV_START
        assert long.membership_and_filters(decision_ms=ELIGIBLE-1)[0]==()
        assert long.membership_and_filters(decision_ms=START)[0]==MEMBERS and len(MEMBERS)>20
        rule,tick=long.filters.rules['BTCUSDT']
        assert type(rule)is C.P.Filters and type(rule.step)is D and rule.tick==tick
        assert long.funding_tail_exclusive_end_ms==END+15001
        with pytest.raises(C.C267Locked,match='OWN_ISSUED'):S.DevelopmentSource(replace(long_cap,side=-1))
        long.side=-1
        with pytest.raises(C.C267Locked,match='SCOPE_OR_IMMUTABLE'):long.native_candles('BTCUSDT')
    with pytest.raises(C.C267Locked,match='ALREADY_SPENT'):
        with A.development_authority(1):pytest.fail('same side reused')
    assert not A._ISSUED


def test_production_default_locked_before_any_source_or_evaluation_identity(monkeypatch):
    monkeypatch.setattr(A,'_git',lambda *args:'a'*40 if args==('rev-parse','HEAD') else '')
    monkeypatch.setattr(A,'_tree',lambda *args:(_ for _ in ()).throw(C.C267Locked('MISSING_OWN_C267_RECEIPT')))
    monkeypatch.setattr(S,'prepare_metadata',lambda *args:pytest.fail('unbound source access'))
    with pytest.raises(C.C267Locked,match='MISSING_OWN_C267_RECEIPT'):
        with A.development_authority(1):pytest.fail('unbound authority')
    with pytest.raises(C.C267Locked,match='OWN_ISSUED'):S.DevelopmentSource(object())


def test_actual_checksum_minute_stream_retains_native_decimal_and_immutable_cache(native_fixture,tmp_path,monkeypatch):
    root=tmp_path/'archive';shutil.copytree(native_fixture,root)
    def changed(lines):
        for i,line in enumerate(lines[1:],1):
            cells=line.split(b',');cells[1:5]=[b'100.00000000000000001']*4;lines[i]=b','.join(cells)
        return lines
    edit_trade(root,changed);issue(monkeypatch,root,tmp_path/'common')
    with A.development_authority(1) as cap:
        source=S.DevelopmentSource(cap);bars=source.native_candles('BTCUSDT')
        assert bars[START].open==D('100.00000000000000001') and bars[START].signal_bar().open==100.
        assert all('/1m/' in r['path'] for r in source.source_reads)
        with pytest.raises(TypeError):bars[START]=None
        source._cache['BTCUSDT','klines']={}
        with pytest.raises(C.C267Locked,match='CACHE_REPLACED'):source.native_candles('BTCUSDT')


def test_first_valid_exact_suffix_unavailable_even_inside_720h_history(native_fixture,tmp_path,monkeypatch):
    root=tmp_path/'archive';shutil.copytree(native_fixture,root)
    edit_trade(root,lambda lines:[lines[0]]+lines[31:]);issue(monkeypatch,root,tmp_path/'common')
    with A.development_authority(1) as cap:
        source=S.DevelopmentSource(cap)
        assert source.view.required_intervals('BTCUSDT')[0][0]<=START
        assert tuple(source.native_candles('BTCUSDT'))==(START+H,START+2*H)
        assert 'REQUIRES_FULL_HISTORY_WARMUP' in source.known_gaps[-1]['reason']


@pytest.mark.parametrize('attack',['suffix_hole','second_partial','internal_gap'])
def test_second_or_invalid_initial_partial_and_required_internal_gap_fail(native_fixture,tmp_path,monkeypatch,attack):
    root=tmp_path/'archive';shutil.copytree(native_fixture,root)
    def changed(lines):
        if attack=='suffix_hole':return [lines[0]]+lines[31:40]+lines[41:]
        if attack=='second_partial':return lines[:-1]
        return [lines[0]]+[v for v in lines[1:] if not START+H<=int(v.split(b',',1)[0])<START+2*H]
    edit_trade(root,changed);issue(monkeypatch,root,tmp_path/'common')
    with A.development_authority(1) as cap:
        with pytest.raises(S.SourceIncomplete):S.DevelopmentSource(cap).native_candles('BTCUSDT')


def test_published_funding_transition_proof_and_issued_identity_cache(tmp_path):
    rows=[f'{START},8,.001'.encode(),f'{START+8*H},4,.002'.encode()]
    record=archive(tmp_path,'BTCUSDT','fundingRate',1,rows)
    selected,proof=S.authenticated_funding_month(tmp_path,record,START,START+10*H)
    assert [v.interval_hours for v in selected]==[8,4] and proof.rows==2
    bad=dict(record,rows=1)
    with pytest.raises(S.SourceIncomplete,match='ALL_RECORD'):S.authenticated_funding_month(tmp_path,bad,START,START+10*H)


def test_own_zero_quote_signal_projection_and_full_atr_price_parity():
    native=[]
    for i in range(28):
        width=D('4') if i<3 else D('.5')
        native.append(S.NativeBar(START+i*H,D(100),D(100)+width,D(100)-width,D(100),D(0) if i%2 else D(10)))
    projected=tuple(v.signal_bar() for v in native)
    assert isinstance(projected[1],S.P.Bar) and projected[1].quote_volume==0
    assert len(S.P.exact_index(projected))==28
    positive=tuple(S.P.Bar(v.open_ms,v.open,v.high,v.low,v.close,10.) for v in projected)
    for count in(25,26,28):
        decision=START+count*H
        assert S.P.atr24_wilder(projected[:count],decision)==S.P.atr24_wilder(positive[:count],decision)
    with pytest.raises(S.SourceIncomplete):replace(native[0],quote_volume=D(-1)).signal_bar()
